def _fold(tok):
    out = {tok}
    for suf in ("ies", "es", "s"):
        if len(tok) > len(suf) + 2 and tok.endswith(suf):
            out.add(tok[: -len(suf)])
            if suf == "ies":
                out.add(tok[: -3] + "y")
    return out


def _group_ok(group, forms, tokens):
    for alt in group.split("|"):
        if alt.endswith("*"):
            stem = alt[:-1]
            if any(t.startswith(stem) for t in tokens):
                return True
        elif alt in forms:
            return True
    return False


def propose(ctx: "Context") -> Optional[Proposal]:
    tokens = list(ctx.tokens)
    if not tokens:
        return None
    forms = set()
    for t in tokens:
        forms |= _fold(t)
    best = None
    best_score = -1
    for groups, answer in E:
        if all(_group_ok(g, forms, tokens) for g in groups):
            score = len(groups)
            if score > best_score:
                best, best_score = answer, score
    if best is None:
        return None
    return Proposal(best, min(0.74 + 0.03 * best_score, 0.88))
